import urllib.request, urllib.parse, json, time

# 1. Fetch PDB FASTA for all IDs
ids = open('/app/pdb_ids.txt').read().split()
print("=== PDB FASTA FETCH ===")
for pid in ids:
    url = f"https://www.rcsb.org/fasta/entry/{pid}/display"
    try:
        with urllib.request.urlopen(url, timeout=15) as r:
            data = r.read().decode()
        lines = data.strip().split('\n')
        headers = [l for l in lines if l.startswith('>')]
        seqs = []
        cur = []
        for l in lines:
            if l.startswith('>'):
                if cur:
                    seqs.append(''.join(cur)); cur=[]
            else:
                cur.append(l.strip())
        if cur: seqs.append(''.join(cur))
        print(f"\n{pid}: {len(seqs)} chain(s)")
        for h,s in zip(headers, seqs):
            print(f"  {h[:100]}")
            print(f"  seq_len={len(s)} seq_start={s[:60]}")
    except Exception as e:
        print(f"{pid}: ERROR {e}")
    time.sleep(0.2)

# 2. Try fpbase API endpoints
print("\n=== FPBASE API ===")
for endpoint in ["https://www.fpbase.org/api/proteins/", "https://www.fpbase.org/api/spectra/", "https://fpbase.org/api/proteins/"]:
    try:
        with urllib.request.urlopen(endpoint, timeout=15) as r:
            data = r.read().decode()
        print(f"{endpoint}: {len(data)} bytes, start={data[:200]}")
    except Exception as e:
        print(f"{endpoint}: ERROR {e}")

