import urllib.request, urllib.parse, json, time

headers = {"User-Agent": "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"}

def fetch(url, data=None, timeout=20):
    req = urllib.request.Request(url, data=data, headers=headers)
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return r.read().decode()

# 1. fpbase with headers
print("=== FPBASE WITH HEADERS ===")
for endpoint in ["https://www.fpbase.org/api/proteins/", "https://www.fpbase.org/api/spectra/", "https://www.fpbase.org/api/"]:
    try:
        data = fetch(endpoint)
        print(f"{endpoint}: {len(data)} bytes, start={data[:300]}")
    except Exception as e:
        print(f"{endpoint}: ERROR {e}")

# Try fpbase search for specific proteins
print("\n=== FPBASE SPECIFIC ===")
for name in ["mCherry", "EGFP", "GFP", "TagRFP", "mCherry2", "Azami Green"]:
    try:
        url = f"https://www.fpbase.org/api/proteins/?name={urllib.parse.quote(name)}"
        data = fetch(url)
        print(f"{name}: {data[:400]}")
    except Exception as e:
        print(f"{name}: ERROR {e}")

# 2. RCSB ligand info for 3KZY and chemical component search
print("\n=== RCSB LIGAND INFO ===")
for pid in ["3KZY", "5P21", "1AK4"]:
    try:
        url = f"https://data.rcsb.org/rest/v1/core/entry/{pid}"
        data = json.loads(fetch(url))
        # Get non-polymer entities
        nonpoly = [e for e in data.get("rcsb_entry_container_identifiers", {}).get("non_polymer_entity_ids", [])]
        print(f"{pid} non_polymer_entities: {nonpoly}")
    except Exception as e:
        print(f"{pid} entry: ERROR {e}")

# Get chemical component details for 3KZY
print("\n=== 3KZY NONPOLYMER DETAILS ===")
try:
    url = "https://data.rcsb.org/rest/v1/core/nonpolymer_entity/3KZY"
    data = json.loads(fetch(url))
    print(json.dumps(data, indent=2)[:2000])
except Exception as e:
    print(f"3KZY nonpoly: ERROR {e}")

# Search PDB chem comp by name/smiles
print("\n=== RCSB CHEM SEARCH ===")
smiles = "Nc3nc(OCc1ccccc1)c2nc[nH]c2n3"
for search_type in ["exact", "similarity"]:
    query = {
        "query": {
            "type": "terminal",
            "service": "chemical",
            "parameters": {"value": smiles, "type": search_type, "limit": 10}
        },
        "return_type": "entry",
        "request_options": {"return_all_hits": True}
    }
    try:
        data = fetch("https://search.rcsb.org/rcsbsearch/v2/query", json.dumps(query).encode())
        result = json.loads(data)
        print(f"{search_type}: {json.dumps(result, indent=2)[:800]}")
    except Exception as e:
        print(f"{search_type}: ERROR {e}")

# 3. Search for antibody target - try NCBI BLAST URL API
print("\n=== ANTIBODY TARGET SEARCH ===")
hv = "QVQLQQSAAELARPGASVKMSCKASGYSFTTYTIHWVKQRPGQGLEWIGYINPSSGYAAYNQNFKDETTLTADPSSSTAYMELNSLTSEDSAVYYCAREKFYGYDYWGQGATLTVSS"
lv = "DVLMTQIPLSLPVSLGDQASISCRSSQSIVHRNGNTYLEWYLLKPGQSPKLLIYKVSNRFSGVPDRFSGSGSGTDFTLKISRVEAEDLGVYYCFQGSHVPYTFGGGTKLEIK"

# Try UniProt search by sequence
for label, seq in ["heavy_v", hv], ["light_v", lv]:
    try:
        url = f"https://rest.uniprot.org/search?query={urllib.parse.quote(seq[:30])}&format=json&size=5"
        data = fetch(url)
        print(f"UniProt {label} search: {data[:500]}")
    except Exception as e:
        print(f"UniProt {label}: ERROR {e}")

# Try searching NCBI for the CDR3 sequences
print("\n=== CDR SEARCH ===")
for cdr in ["AREKFYGYDY", "FQGSHVPYT"]:
    try:
        url = f"https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?db=protein&term={urllib.parse.quote(cdr)}&retmode=json&retmax=5"
        data = json.loads(fetch(url))
        print(f"CDR {cdr}: {json.dumps(data, indent=2)[:500]}")
    except Exception as e:
        print(f"CDR {cdr}: ERROR {e}")

# 4. Save all full PDB FASTA sequences
print("\n=== SAVING PDB FASTA ===")
ids = open('/app/pdb_ids.txt').read().split()
with open('/app/pdb_fasta_all.txt', 'w') as out:
    for pid in ids:
        url = f"https://www.rcsb.org/fasta/entry/{pid}/display"
        try:
            data = fetch(url)
            out.write(data)
            if not data.endswith('\n'): out.write('\n')
            print(f"{pid}: saved {len(data)} bytes")
        except Exception as e:
            print(f"{pid}: ERROR {e}")
        time.sleep(0.2)

